#[test]
fn ciatan_parity() {
    for (a, want) in ATAN {
        let got = ciatan(f64::from_bits(*a)).to_bits();
        if got != *want && f64::from_bits(*a).is_nan() && f64::from_bits(got).is_nan() {
            continue;
        }
        assert_eq!(got, *want, "ciatan {a:#018x}");
    }
}

#[test]
fn ciexp_parity() {
    for (a, want) in EXPT {
        let got = ciexp(f64::from_bits(*a)).to_bits();
        assert_eq!(got, *want, "ciexp {a:#018x}");
    }
}

#[test]
fn cilog_parity() {
    for (a, want) in LOGT {
        let got = cilog(f64::from_bits(*a)).to_bits();
        if got != *want && f64::from_bits(*a).is_nan() && f64::from_bits(got).is_nan() {
            continue;
        }
        assert_eq!(got, *want, "cilog {a:#018x}");
    }
}
